mapper.select:
SELECT NVL(B.DETAIL_SUBJECT_NO,B.SUBJECT_NO) AS subjectNo, NVL(B.DETAIL_SUBJECT_NAME,B.SUBJECT_NAME) AS subjectName, (case when B.SUBJECT_NO like '7%' and B.CD_FLAG ='C' THEN '付' when B.SUBJECT_NO like '7%' and B.CD_FLAG ='D' THEN '收' when B.SUBJECT_NO not like '7%' and B.CD_FLAG ='C' THEN '贷' when B.SUBJECT_NO not like '7%' and B.CD_FLAG ='D' THEN '借' END ) cdFlag, B.ccy AS ccy, B.HAPPEN_AMT AS happenAmt, B.B_CCY as bCcy, B.B_HAPPEN_AMT as bHappenAmt, B.HAPPEN_NUMBER AS happenNumber FROM bok_VOUCH_DETAIL B JOIN bok_VOUCH_MAIN A ON A.VOUCH_NUM = B.VOUCH_NUM LEFT JOIN BOK_BOOKSET bb ON BB.BOOKSET_ID = A.BOOKSET_ID -- LEFT JOIN BOK_SUBJECT bs -- ON bs.BOOKSET_ID = bb.BOOKSET_ID_TMPL -- AND bs.SUBJECT_NO = B.SUBJECT_NO -- LEFT JOIN BOK_BUSS_DETSUB bbd -- ON bbd.BOOKSET_ID = A.BOOKSET_ID -- AND bbd.DETAIL_SUBJECT_NO = B.DETAIL_SUBJECT_NO WHERE 1=1
AND A.BUS_VOUCHNUM = #{busVouchnum}
AND A.BOOKSET_ID = #{booksetId}
AND B.TABLE_ID = #{tableId}
AND A.BOOK_DATE = to_date(#{bookDate},'yyyy-mm-dd')
AND B.SUBJECT_NO = #{subjectNo}
ORDER by B.CD_FLAG DESC , NVL(B.DETAIL_SUBJECT_NO, B.SUBJECT_NO) ASC
